const LESSONS = {"en":{"foundations":{"title":"Stock Market Foundations","level":"beginner","time":"6 lessons","summary":"What a share is, how exchanges work, and how an order becomes a trade."},"investing":{"title":"Investing & Wealth Building","level":"beginner","time":"8 lessons","summary":"Set goals, understand your time horizon, diversify, and let compounding work over years."},"sip-mutual-funds":{"title":"SIP & Mutual Funds","level":"beginner","time":"7 lessons","summary":"How a Systematic Investment Plan works, what NAV means, and how to read fund costs."},"reading-charts":{"title":"Reading Charts","level":"beginner","time":"6 lessons","summary":"Understand line, bar and candlestick charts, OHLC data, and volume."},"fundamental-analysis":{"title":"Fundamental Analysis","level":"intermediate","time":"9 lessons","summary":"Evaluate a business using its financial statements, key ratios and quality checks."},"technical-analysis":{"title":"Technical Analysis","level":"intermediate","time":"10 lessons","summary":"Study price and volume patterns, trends, support, resistance and common indicators."},"swing-trading":{"title":"Swing Trading","level":"intermediate","time":"8 lessons","summary":"Hold trades for days to weeks using clear setups, entry and exit rules, and a trade journal."},"risk-management":{"title":"Risk Management","level":"intermediate","time":"7 lessons","summary":"Protect your capital with position sizing, stop losses, exposure limits and a drawdown plan."},"intraday-trading":{"title":"Intraday Trading","level":"advanced","time":"9 lessons","summary":"Trade within one session. Understand liquidity, order execution, margin and the real risks."},"futures-options":{"title":"Futures & Options","level":"advanced","time":"12 lessons","summary":"Understand futures, call and put options, strike price, expiry, margin and payoff, along with their risks."},"option-greeks":{"title":"Option Greeks & Strategies","level":"advanced","time":"10 lessons","summary":"Measure how option prices respond to price, time and volatility, and build defined-risk strategies.","sections":[{"h":"Delta","p":"Delta estimates how much an option's price changes for a ₹1 move in the underlying. A call's delta runs from 0 to 1, and a put's from −1 to 0. A delta near 0.5 is roughly at the money."},{"h":"Gamma and theta","ul":["Gamma: how quickly delta changes as the underlying moves. It is highest near the money and near expiry.","Theta: the daily time decay in an option's value. Option buyers pay theta, and option sellers collect it."]},{"h":"Vega and implied volatility","p":"Vega measures sensitivity to a 1% change in implied volatility (IV). IV reflects the market's expectation of future movement. Options usually become more expensive when IV rises, for example before results or major events."},{"h":"Defined-risk spreads","p":"A bull call spread buys one call and sells a higher-strike call with the same expiry. Both maximum profit and maximum loss are limited. Iron condors and credit spreads are other defined-risk structures. Check the margin and maximum loss before entering."},{"h":"Practical caution","p":"Greeks are model estimates and change quickly. Test strategies in paper trading and understand the assumptions behind your broker's calculator."}]},"trading-psychology":{"title":"Trading Psychology","level":"advanced","time":"6 lessons","summary":"Recognise biases such as fear, greed and overtrading, and build a disciplined process."},"candlestick-patterns":{"title":"Candlestick and Chart Patterns","level":"intermediate","time":"25 patterns","summary":"Learn what each candle and chart shape signals, when it matters, how to confirm it, and the mistake to avoid."},"technical-indicators":{"title":"Technical Indicators","level":"intermediate","time":"10 indicators","summary":"Understand what moving averages, RSI, MACD, volume and other indicators measure, when to use each one, and how to use them in a trade."},"tax-basics":{"title":"Tax Basics for Indian Investors and Traders","level":"intermediate","time":"11 topics","summary":"How gains from shares, mutual funds, intraday and F&O are taxed in India, what records to keep, and where to verify the current rules."},"balance-sheet":{"title":"How to Read a Balance Sheet","level":"intermediate","time":"13 topics","summary":"What a balance sheet shows, how to read assets, liabilities and equity, and the ratios that reveal financial strength."},"cash-flow-statement":{"title":"How to Read a Cash Flow Statement","level":"intermediate","time":"13 topics","summary":"Where a company's real cash comes from and goes, and why cash flow can tell you more than profit."},"quarterly-results":{"title":"How to Read Quarterly Results","level":"intermediate","time":"13 topics","summary":"How to read the numbers in a quarterly results filing, compare them correctly, and spot one-off items."},"annual-report":{"title":"How to Read an Annual Report","level":"intermediate","time":"13 topics","summary":"The parts of a company's annual report, what each section tells you, and the warning signs to look for."},"shareholding-pattern":{"title":"Shareholding Pattern and Promoter Holding","level":"intermediate","time":"12 topics","summary":"Who owns a company, how promoter, institutional and public holdings change, and what pledged shares mean."},"valuation-basics":{"title":"Valuation Basics: What Is a Share Worth?","level":"advanced","time":"8 topics","summary":"P/E, P/B, EV/EBITDA, PEG and discounted cash flow explained, with their limits and how to combine them."},"corporate-actions":{"title":"Corporate Actions: Dividends, Bonus, Splits, Rights and Buybacks","level":"intermediate","time":"13 topics","summary":"What companies do with shares and cash, how each action changes the price and your holding, and how to avoid confusion on the ex-date."},"market-rules":{"title":"Market Rules & Investor Protection","level":"beginner","time":"10 topics","summary":"Market timings, settlement, price bands and circuit breakers, applying for IPOs, spotting scams and tips, and how to complain if something goes wrong."}},"hi":{"foundations":{"title":"शेयर बाज़ार की मूल बातें","level":"beginner","time":"6 पाठ","summary":"शेयर क्या है, एक्सचेंज कैसे काम करते हैं, और ऑर्डर ट्रेड में कैसे बदलता है।"},"investing":{"title":"निवेश और धन निर्माण","level":"beginner","time":"8 पाठ","summary":"लक्ष्य तय करें, समय-सीमा समझें, विविधीकरण करें और चक्रवृद्धि को वर्षों तक काम करने दें।"},"sip-mutual-funds":{"title":"SIP और म्यूचुअल फंड","level":"beginner","time":"7 पाठ","summary":"SIP कैसे काम करता है, NAV का मतलब क्या है, और फंड की लागत कैसे पढ़ें।"},"reading-charts":{"title":"चार्ट कैसे पढ़ें","level":"beginner","time":"6 पाठ","summary":"लाइन, बार और कैंडलस्टिक चार्ट, OHLC डेटा और वॉल्यूम समझें।"},"fundamental-analysis":{"title":"फंडामेंटल एनालिसिस","level":"intermediate","time":"9 पाठ","summary":"वित्तीय विवरण, प्रमुख अनुपात और गुणवत्ता जाँच से किसी कारोबार का मूल्यांकन करें।"},"technical-analysis":{"title":"टेक्निकल एनालिसिस","level":"intermediate","time":"10 पाठ","summary":"कीमत और वॉल्यूम पैटर्न, ट्रेंड, सपोर्ट, रेज़िस्टेंस और आम इंडिकेटर पढ़ें।"},"swing-trading":{"title":"स्विंग ट्रेडिंग","level":"intermediate","time":"8 पाठ","summary":"साफ़ सेटअप, एंट्री-एग्ज़िट नियम और ट्रेड जर्नल से कुछ दिनों से कुछ हफ़्तों तक ट्रेड रखें।"},"risk-management":{"title":"जोखिम प्रबंधन","level":"intermediate","time":"7 पाठ","summary":"पोज़िशन साइज़, स्टॉप लॉस, एक्सपोज़र सीमा और ड्रॉडाउन योजना से पूँजी की रक्षा करें।"},"intraday-trading":{"title":"इंट्राडे ट्रेडिंग","level":"advanced","time":"9 पाठ","summary":"एक ही सत्र में ट्रेड करें। लिक्विडिटी, ऑर्डर निष्पादन, मार्जिन और असली जोखिम समझें।"},"futures-options":{"title":"फ्यूचर्स और ऑप्शंस (F&O)","level":"advanced","time":"12 पाठ","summary":"फ्यूचर्स, कॉल और पुट ऑप्शंस, स्ट्राइक, एक्सपायरी, मार्जिन और पेऑफ़ को उनके जोखिमों के साथ समझें।"},"option-greeks":{"title":"ऑप्शन ग्रीक्स और रणनीतियाँ","level":"advanced","time":"10 पाठ","summary":"कीमत, समय और अस्थिरता के साथ ऑप्शन की कीमत कैसे बदलती है, यह समझें और सीमित-जोखिम रणनीतियाँ बनाएँ।","sections":[{"h":"डेल्टा","p":"डेल्टा बताता है कि अंतर्निहित एसेट में ₹1 की चाल पर ऑप्शन की कीमत कितनी बदलेगी। कॉल का डेल्टा 0 से 1 के बीच और पुट का −1 से 0 के बीच होता है। लगभग 0.5 डेल्टा मोटे तौर पर एट द मनी को दर्शाता है।"},{"h":"गामा और थीटा","ul":["गामा: अंतर्निहित एसेट बदलने पर डेल्टा कितनी तेज़ी से बदलता है। एट द मनी और एक्सपायरी के पास सबसे ज़्यादा।","थीटा: ऑप्शन की कीमत का रोज़ का समय-क्षय। ऑप्शन ख़रीदार थीटा चुकाते हैं, और विक्रेता इसे कमाते हैं।"]},{"h":"वेगा और इम्प्लाइड वोलैटिलिटी (IV)","p":"वेगा IV में 1% बदलाव पर संवेदनशीलता मापता है। IV बाज़ार की भविष्य की चाल की उम्मीद दर्शाता है। नतीजों या किसी बड़ी घटना से पहले IV बढ़ने पर ऑप्शन आमतौर पर महँगे हो जाते हैं।"},{"h":"सीमित-जोखिम स्प्रेड","p":"बुल कॉल स्प्रेड में एक कॉल ख़रीदी जाती है और उसी एक्सपायरी की ऊँची स्ट्राइक वाली कॉल बेची जाती है। अधिकतम लाभ और अधिकतम नुकसान दोनों सीमित होते हैं। आयरन कंडोर और क्रेडिट स्प्रेड भी ऐसी संरचनाएँ हैं। एंट्री से पहले मार्जिन और अधिकतम नुकसान जाँचें।"},{"h":"व्यावहारिक सावधानी","p":"ग्रीक्स मॉडल पर आधारित अनुमान हैं और तेज़ी से बदलते हैं। रणनीतियों को पेपर ट्रेडिंग में परखें और अपने ब्रोकर के कैलकुलेटर की धारणाएँ समझें।"}]},"trading-psychology":{"title":"ट्रेडिंग मनोविज्ञान","level":"advanced","time":"6 पाठ","summary":"डर, लालच और ओवरट्रेडिंग जैसे पूर्वाग्रह पहचानें और अनुशासित प्रक्रिया बनाएँ।"},"candlestick-patterns":{"title":"कैंडलस्टिक और चार्ट पैटर्न","level":"intermediate","time":"25 पैटर्न","summary":"हर कैंडल और चार्ट आकार का संकेत, उसका महत्व, पुष्टि कैसे करें, और कौन सी गलती से बचें, यह सीखें।"},"technical-indicators":{"title":"टेक्निकल इंडिकेटर","level":"intermediate","time":"10 इंडिकेटर","summary":"मूविंग एवरेज, RSI, MACD, वॉल्यूम और अन्य इंडिकेटर क्या मापते हैं, हर एक कब इस्तेमाल करें, और ट्रेड में कैसे इस्तेमाल करें, यह समझें।"},"tax-basics":{"title":"भारतीय निवेशकों और ट्रेडरों के लिए टैक्स बेसिक्स","level":"intermediate","time":"11 विषय","summary":"भारत में शेयर, म्यूचुअल फंड, इंट्राडे और F&O से होने वाले लाभ पर टैक्स कैसे लगता है, कौन से रिकॉर्ड रखें, और मौजूदा नियम कहाँ जाँचें।"},"balance-sheet":{"title":"बैलेंस शीट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"बैलेंस शीट क्या दिखाती है, संपत्ति, देनदारी और इक्विटी कैसे पढ़ें, और वित्तीय मज़बूती बताने वाले अनुपात।"},"cash-flow-statement":{"title":"कैश फ़्लो स्टेटमेंट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"कंपनी का असली नकद कहाँ से आता और कहाँ जाता है, और कैश फ़्लो मुनाफ़े से ज़्यादा क्या बताता है।"},"quarterly-results":{"title":"तिमाही नतीजे कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"तिमाही नतीजों के आँकड़े कैसे पढ़ें, सही तुलना कैसे करें, और एक-बार की मदों को कैसे पहचानें।"},"annual-report":{"title":"सालाना रिपोर्ट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"कंपनी की सालाना रिपोर्ट के हिस्से, हर हिस्सा क्या बताता है, और चेतावनी के संकेत।"},"shareholding-pattern":{"title":"शेयरहोल्डिंग पैटर्न और प्रमोटर होल्डिंग","level":"intermediate","time":"12 विषय","summary":"कंपनी का मालिक कौन है, प्रमोटर, संस्थागत और सार्वजनिक होल्डिंग कैसे बदलती है, और गिरवी शेयरों का क्या मतलब है।"},"valuation-basics":{"title":"वैल्यूएशन की मूल बातें: शेयर की क़ीमत क्या होनी चाहिए?","level":"advanced","time":"8 विषय","summary":"P/E, P/B, EV/EBITDA, PEG और डिस्काउंटेड कैश फ़्लो समझाए गए, उनकी सीमाओं के साथ और उन्हें मिलाकर कैसे इस्तेमाल करें।"},"corporate-actions":{"title":"कॉर्पोरेट एक्शन: डिविडेंड, बोनस, स्प्लिट, राइट्स और बायबैक","level":"intermediate","time":"13 विषय","summary":"कंपनियाँ शेयर और नकद के साथ क्या करती हैं, हर एक्शन कीमत और आपकी होल्डिंग को कैसे बदलता है, और एक्स-डेट पर भ्रम से कैसे बचें।"},"market-rules":{"title":"बाज़ार के नियम और निवेशक सुरक्षा","level":"beginner","time":"10 विषय","summary":"बाज़ार का समय, सेटलमेंट, प्राइस बैंड और सर्किट ब्रेकर, IPO में आवेदन, धोखाधड़ी और टिप्स पहचानना, और कुछ गलत होने पर शिकायत कैसे करें।"}}};
const LESSON_OVERRIDES = {"en":{"option-greeks":{"sections":[{"h":"1. What the Greeks measure","p":"The Greeks are sensitivities: how much an option's price changes when one input changes. They come from pricing models and are estimates that move as the market moves. Learning them turns vague feelings ('the option should rise') into measurable exposures. The main inputs are the underlying price, time to expiry, implied volatility and interest rates."},{"h":"2. Delta: sensitivity to the price","p":"Delta is the change in option price for a ₹1 change in the underlying. Call deltas run from 0 to 1, and put deltas from −1 to 0. An at-the-money option has delta near 0.5 for calls. Delta also approximates the probability the option expires in the money, which is a useful rough guide.","p2":"Example: a call with delta 0.6 gains about ₹60 per unit if the underlying rises ₹100 (0.6 × 100). If the underlying falls ₹100, it loses about ₹60. Delta changes as the price moves, so the estimate is only good for small moves."},{"h":"3. Gamma: how fast delta changes","p":"Gamma is the rate of change of delta. It is highest for at-the-money options close to expiry. High gamma means small price moves can change your exposure quickly. Option buyers have positive gamma and benefit from large moves. Option sellers have negative gamma and are hurt by large moves, which is why sellers need hedging discipline."},{"h":"4. Theta: the cost of time","p":"Theta is the daily decline in an option's time value, all else equal. Option buyers pay theta; sellers collect it. Theta is largest for at-the-money options near expiry, which is why short-dated options can lose value quickly even when the underlying does not move.","p2":"Example: an option priced at ₹100 with theta −5 per day. After two days, all else equal, it is about ₹90. The decay is not linear; it speeds up near expiry."},{"h":"5. Vega and implied volatility","p":"Vega is the change in option price for a 1 percentage point change in implied volatility (IV). IV is the volatility implied by the option's price. When uncertainty rises, IV rises and options get more expensive. Before results, budgets and elections, IV often rises. After the event, IV often falls sharply, which is called IV crush.","p2":"Example: vega 8, IV rises 2 points: the option gains about ₹16 per unit even if the underlying does not move. If IV then falls 4 points after results, the option can lose value even if the stock moves in the expected direction."},{"h":"6. Rho: interest rates","p":"Rho measures sensitivity to interest rates. For short-dated options it is usually small and often ignored by beginners. It matters more for long-dated options and in periods of rate changes."},{"h":"7. Using the Greeks together","p":"No single Greek explains the position. A practical checklist: delta tells you the direction exposure; theta tells you the daily cost or income; vega tells you how exposed you are to a change in uncertainty; gamma tells you how the exposure will change as price moves. Before any trade, write down the Greeks and what would make them change."},{"h":"8. Defined-risk strategies","p":"A defined-risk strategy limits both maximum loss and maximum profit. Spreads do this by buying one option and selling another. They reduce cost and reduce the impact of volatility changes.","ul":["Bull call spread: buy a lower-strike call and sell a higher-strike call with the same expiry. Profits if the price rises moderately.","Bear put spread: buy a higher-strike put and sell a lower-strike put. Profits if the price falls moderately.","Iron condor: sell an out-of-the-money put spread and an out-of-the-money call spread. Profits if the price stays in a range. Limited profit, limited loss."]},{"h":"9. Worked example: bull call spread","p":"Buy a 24,000 call at ₹200 premium and sell a 24,500 call at ₹80 premium. Net debit ₹120. Maximum profit = 500 − 120 = ₹380 per unit. Maximum loss = ₹120 per unit. Break-even = 24,000 + 120 = 24,120. Both risk and reward are fixed before entry. The trade is a view that the index rises to around 24,500 by expiry, with the loss capped if it does not."},{"h":"10. Volatility as a trade","p":"Some traders trade volatility itself: buying options when IV is low and expected to rise, or selling when IV is high and expected to fall. Compare current IV with its historical range to judge whether options are cheap or expensive. A high IV is not a reason to sell on its own, because high volatility often comes with large moves."},{"h":"11. Practical cautions","ul":["Model estimates depend on inputs. Check your broker's calculator and understand its assumptions.","Liquidity matters. Wide bid-ask spreads make Greeks hard to trust and exits expensive.","Time decay is relentless for buyers. A correct view can still lose money if the move is too slow.","Expiry week changes gamma and theta sharply. Know your exposure before the final days.","Paper-trade a strategy before risking money, and keep a record of the Greeks at entry and exit."]},{"h":"12. Common Greeks mistakes","ul":["Buying options only because they look cheap, ignoring theta.","Ignoring IV when buying before results.","Selling naked options without understanding gamma risk.","Assuming delta stays the same as the price moves.","Using the Greeks without knowing the expiry date and strike."]}]}},"hi":{"option-greeks":{"sections":[{"h":"1. ग्रीक्स क्या मापते हैं","p":"ग्रीक्स संवेदनशीलताएँ हैं: किसी एक इनपुट के बदलने पर ऑप्शन की कीमत कितनी बदलती है। ये प्राइसिंग मॉडल से आते हैं और बाज़ार के साथ बदलने वाले अनुमान हैं। इन्हें समझने से अस्पष्ट भावना ('ऑप्शन चढ़ना चाहिए') मापने योग्य एक्सपोज़र बन जाती है। मुख्य इनपुट हैं: अंतर्निहित कीमत, एक्सपायरी तक का समय, इम्प्लाइड वोलैटिलिटी और ब्याज दर।"},{"h":"2. डेल्टा: कीमत के प्रति संवेदनशीलता","p":"डेल्टा अंतर्निहित में ₹1 के बदलाव पर ऑप्शन की कीमत में बदलाव है। कॉल का डेल्टा 0 से 1 और पुट का −1 से 0 के बीच। एट-द-मनी कॉल का डेल्टा लगभग 0.5 होता है। डेल्टा यह भी लगभग बताता है कि ऑप्शन इन द मनी एक्सपायर होगा, जो एक उपयोगी मोटा अनुमान है।","p2":"उदाहरण: 0.6 डेल्टा वाली कॉल, अंतर्निहित ₹100 चढ़े तो लगभग ₹60 प्रति यूनिट बढ़ती है (0.6 × 100)। अंतर्निहित ₹100 गिरे तो लगभग ₹60 घटती है। डेल्टा कीमत के साथ बदलता है, इसलिए यह अनुमान छोटी चाल के लिए ही अच्छा है।"},{"h":"3. गामा: डेल्टा कितनी तेज़ी से बदलता है","p":"गामा डेल्टा के बदलने की दर है। यह एट-द-मनी और एक्सपायरी के पास के ऑप्शन में सबसे ज़्यादा होता है। ज़्यादा गामा का मतलब है कि छोटी कीमत चाल भी आपका एक्सपोज़र जल्दी बदल सकती है। ऑप्शन ख़रीदारों का गामा सकारात्मक है और उन्हें बड़ी चाल से फ़ायदा होता है। ऑप्शन विक्रेताओं का गामा नकारात्मक है और बड़ी चाल उन्हें नुकसान देती है, इसलिए विक्रेताओं को हेजिंग का अनुशासन चाहिए।"},{"h":"4. थीटा: समय की कीमत","p":"थीटा अन्य सब समान रहने पर ऑप्शन के समय मूल्य में रोज़ की गिरावट है। ऑप्शन ख़रीदार थीटा चुकाते हैं; विक्रेता इसे कमाते हैं। थीटा एक्सपायरी के पास एट-द-मनी ऑप्शन में सबसे ज़्यादा होता है, इसलिए छोटी अवधि के ऑप्शन अंतर्निहित न चलने पर भी तेज़ी से मूल्य खो सकते हैं।","p2":"उदाहरण: ₹100 पर कीमत वाला ऑप्शन, थीटा −5 प्रतिदिन। दो दिन बाद, बाक़ी सब समान, लगभग ₹90। क्षय सीधी रेखा में नहीं है; एक्सपायरी के पास तेज़ होता है।"},{"h":"5. वेगा और इम्प्लाइड वोलैटिलिटी","p":"वेगा इम्प्लाइड वोलैटिलिटी (IV) में 1 प्रतिशत बिंदु के बदलाव पर ऑप्शन की कीमत में बदलाव है। IV ऑप्शन की कीमत से निकली अस्थिरता है। अनिश्चितता बढ़ने पर IV बढ़ता है और ऑप्शन महँगे होते हैं। नतीजों, बजट और चुनावों से पहले IV अक्सर बढ़ता है। घटना के बाद IV अक्सर तेज़ी से गिरता है, जिसे IV क्रश कहते हैं।","p2":"उदाहरण: वेगा 8, IV 2 अंक बढ़ा: अंतर्निहित न चले तब भी ऑप्शन लगभग ₹16 प्रति यूनिट बढ़ता है। नतीजों के बाद IV 4 अंक गिरे, तो स्टॉक अपेक्षित दिशा में चलकर भी ऑप्शन घट सकता है।"},{"h":"6. रो: ब्याज दरें","p":"रो ब्याज दरों के प्रति संवेदनशीलता मापता है। छोटी अवधि के ऑप्शन में यह आमतौर पर छोटा होता है और शुरुआती अक्सर इसे नज़रअंदाज़ करते हैं। लंबी अवधि के ऑप्शन और दर बदलाव के दौर में यह ज़्यादा मायने रखता है।"},{"h":"7. ग्रीक्स को एक साथ इस्तेमाल करना","p":"कोई एक ग्रीक पूरी पोज़िशन नहीं समझाता। व्यावहारिक जाँच: डेल्टा बताता है दिशा का एक्सपोज़र; थीटा बताता है रोज़ की लागत या आय; वेगा बताता है अनिश्चितता बदलने का असर; गामा बताता है कीमत चलने पर एक्सपोज़र कैसे बदलेगा। किसी भी ट्रेड से पहले ग्रीक्स और उन्हें बदलने वाली स्थितियाँ लिख लें।"},{"h":"8. सीमित-जोखिम रणनीतियाँ","p":"सीमित-जोखिम रणनीति अधिकतम नुकसान और अधिकतम लाभ दोनों सीमित करती है। स्प्रेड एक ऑप्शन ख़रीदकर और दूसरा बेचकर ऐसा करते हैं। ये लागत घटाते हैं और अस्थिरता बदलाव का असर कम करते हैं।","ul":["बुल कॉल स्प्रेड: एक निचली स्ट्राइक की कॉल ख़रीदें और उसी एक्सपायरी की ऊँची स्ट्राइक की कॉल बेचें। मध्यम तेज़ी में लाभ।","बियर पुट स्प्रेड: एक ऊँची स्ट्राइक का पुट ख़रीदें और निचली स्ट्राइक का पुट बेचें। मध्यम गिरावट में लाभ।","आयरन कंडोर: आउट-ऑफ़-द-मनी पुट स्प्रेड और कॉल स्प्रेड बेचें। कीमत रेंज में रहे तो लाभ। सीमित लाभ, सीमित नुकसान।"]},{"h":"9. काम किया हुआ उदाहरण: बुल कॉल स्प्रेड","p":"24,000 कॉल ₹200 प्रीमियम पर ख़रीदें और 24,500 कॉल ₹80 पर बेचें। नेट डेबिट ₹120। अधिकतम लाभ = 500 − 120 = प्रति यूनिट ₹380। अधिकतम नुकसान = प्रति यूनिट ₹120। ब्रेक-ईवन = 24,000 + 120 = 24,120। जोखिम और इनाम एंट्री से पहले तय। ट्रेड का नज़रिया है कि एक्सपायरी तक इंडेक्स लगभग 24,500 तक जाए, और न गया तो नुकसान सीमित।"},{"h":"10. अस्थिरता को ट्रेड के रूप में","p":"कुछ ट्रेडर अस्थिरता ख़ुद ट्रेड करते हैं: IV कम हो और बढ़ने की उम्मीद हो तो ऑप्शन ख़रीदना, या IV ऊँचा हो और गिरने की उम्मीद हो तो बेचना। यह जाँचने के लिए कि ऑप्शन सस्ते हैं या महँगे, मौजूदा IV की ऐतिहासिक सीमा से तुलना करें। ऊँचा IV अकेला बेचने का कारण नहीं, क्योंकि ऊँची अस्थिरता के साथ अक्सर बड़ी चालें आती हैं।"},{"h":"11. व्यावहारिक सावधानियाँ","ul":["मॉडल के अनुमान इनपुट पर निर्भर हैं। अपने ब्रोकर का कैलकुलेटर जाँचें और उसकी धारणाएँ समझें।","लिक्विडिटी मायने रखती है। चौड़े बिड-आस्क स्प्रेड ग्रीक्स को भरोसेमंद नहीं रहने देते और एग्ज़िट महँगा करते हैं।","ख़रीदारों के लिए समय-क्षय निरंतर है। सही नज़रिया भी पैसा खो सकता है, अगर चाल बहुत धीमी हो।","एक्सपायरी सप्ताह में गामा और थीटा तेज़ी से बदलते हैं। आख़िरी दिनों से पहले अपना एक्सपोज़र समझें।","पैसा लगाने से पहले रणनीति पेपर पर परखें, और एंट्री व एग्ज़िट पर ग्रीक्स का रिकॉर्ड रखें।"]},{"h":"12. आम ग्रीक्स गलतियाँ","ul":["थीटा को अनदेखा करके केवल इसलिए ऑप्शन ख़रीदना कि वे सस्ते लगते हैं।","नतीजों से पहले ख़रीदते समय IV को अनदेखा करना।","गामा जोखिम समझे बिना नेकेड ऑप्शन बेचना।","यह मानना कि कीमत चलने पर डेल्टा वही रहता है।","एक्सपायरी और स्ट्राइक जाने बिना ग्रीक्स इस्तेमाल करना।"]}]}}};
const LESSON_EXTRAS_EN = {"option-greeks":{"examples":[{"title":"Delta in action","text":"A call with delta 0.6 gains about 0.6 × 100 = ₹60 per unit if the underlying rises 100 points. Delta is an estimate that changes as the price moves."},{"title":"Theta decay","text":"An option is priced at 100 with theta of −5 per day. After two days, all else equal, it is about 90. Time works against option buyers and in favour of option sellers."},{"title":"Vega and implied volatility","text":"Vega is 8. If implied volatility rises 2 points, the option gains about 8 × 2 = ₹16 per unit, even if the underlying does not move. This is why options often get more expensive before results."},{"title":"Bull call spread","text":"Buy a 24,000 call at ₹200 and sell a 24,500 call at ₹80. Net debit = ₹120. Maximum profit = 500 − 120 = ₹380. Maximum loss = ₹120. Break-even = 24,000 + 120 = 24,120. Both risk and reward are fixed in advance."}],"scenarios":[{"title":"IV crush after results","text":"You buy calls before results when implied volatility is high. The result is in line, and IV falls sharply. The option loses value even though the stock rose a little. Vega losses can exceed directional gains."},{"title":"Weekend time decay","text":"Options lose time value over the weekend even though the market is closed. Option sellers collect theta, but must manage the risk of a large move."}],"useCases":["Choosing between a naked call and a bull call spread to reduce cost and risk.","Using delta to estimate how a portfolio of options moves with the market.","Selling iron condors in a range-bound market with defined maximum loss."],"takeaways":["Delta = price sensitivity; gamma = how delta changes; theta = time decay; vega = volatility sensitivity.","Check implied volatility before buying options.","Defined-risk spreads cap both maximum loss and maximum gain.","Greeks are estimates from a model; verify with your broker's calculator."],"practice":[{"q":"A call has delta 0.4. The underlying rises 50 points. Approximately how much does the option gain?","a":"0.4 × 50 = ₹20 per unit."},{"q":"A spread buys a 100 call for 8 and sells a 110 call for 3. Maximum loss and maximum profit per unit?","a":"Net debit 5. Maximum loss ₹5. Maximum profit 10 − 5 = ₹5."},{"q":"Why can an option lose value even when the stock rises?","a":"Time decay (theta) or a fall in implied volatility (vega) can outweigh a small directional gain."}]}};
const LESSON_EXTRAS_HI = {"option-greeks":{"examples":[{"title":"डेल्टा का असर","text":"0.6 डेल्टा वाली कॉल, अंतर्निहित एसेट 100 अंक चढ़े तो लगभग 0.6 × 100 = ₹60 प्रति यूनिट बढ़ती है। डेल्टा एक अनुमान है जो कीमत बदलने के साथ बदलता है।"},{"title":"थीटा का क्षय","text":"एक ऑप्शन की कीमत 100 है और थीटा −5 प्रति दिन। दो दिन बाद, बाक़ी सब समान रहे, तो लगभग 90। समय ऑप्शन ख़रीदारों के ख़िलाफ़ और विक्रेताओं के पक्ष में काम करता है।"},{"title":"वेगा और इम्प्लाइड वोलैटिलिटी","text":"वेगा 8 है। इम्प्लाइड वोलैटिलिटी 2 अंक बढ़े तो ऑप्शन लगभग 8 × 2 = ₹16 प्रति यूनिट बढ़ता है, भले ही अंतर्निहित एसेट न चले। इसीलिए नतीजों से पहले ऑप्शन अक्सर महँगे हो जाते हैं।"},{"title":"बुल कॉल स्प्रेड","text":"24,000 की कॉल ₹200 पर ख़रीदें और 24,500 की कॉल ₹80 पर बेचें। नेट डेबिट = ₹120। अधिकतम लाभ = 500 − 120 = ₹380। अधिकतम नुकसान = ₹120। ब्रेक-ईवन = 24,000 + 120 = 24,120। जोखिम और इनाम दोनों पहले से तय हैं।"}],"scenarios":[{"title":"नतीजों के बाद IV का गिरना","text":"नतीजों से पहले जब इम्प्लाइड वोलैटिलिटी ऊँची होती है, आप कॉल ख़रीदते हैं। नतीजे अपेक्षा के अनुरूप आते हैं और IV तेज़ी से गिरता है। शेयर थोड़ा चढ़ने पर भी ऑप्शन की कीमत गिर जाती है। वेगा का नुकसान दिशा के लाभ से बड़ा हो सकता है।"},{"title":"सप्ताहांत का समय-क्षय","text":"बाज़ार बंद होने पर भी सप्ताहांत में ऑप्शन की टाइम वैल्यू घटती है। विक्रेता थीटा कमाते हैं, पर उन्हें बड़ी चाल के जोखिम को संभालना होता है।"}],"useCases":["नेकेड कॉल और बुल कॉल स्प्रेड के बीच चुनाव, लागत और जोखिम घटाने के लिए।","ऑप्शन पोर्टफ़ोलियो बाज़ार के साथ कैसे चलेगा, यह डेल्टा से अनुमान लगाना।","सीमित अधिकतम नुकसान के साथ रेंज-बाउंड बाज़ार में आयरन कंडोर बेचना।"],"takeaways":["डेल्टा = कीमत संवेदनशीलता; गामा = डेल्टा कैसे बदलता है; थीटा = समय क्षय; वेगा = अस्थिरता संवेदनशीलता।","ऑप्शन ख़रीदने से पहले इम्प्लाइड वोलैटिलिटी जाँचें।","परिभाषित-जोखिम स्प्रेड अधिकतम नुकसान और अधिकतम लाभ दोनों सीमित करते हैं।","ग्रीक्स मॉडल से निकले अनुमान हैं; अपने ब्रोकर के कैलकुलेटर से जाँचें।"],"practice":[{"q":"एक कॉल का डेल्टा 0.4 है। अंतर्निहित एसेट 50 अंक चढ़ता है। ऑप्शन लगभग कितना बढ़ेगा?","a":"0.4 × 50 = ₹20 प्रति यूनिट।"},{"q":"एक स्प्रेड में 100 की कॉल 8 पर ख़रीदी और 110 की कॉल 3 पर बेची। प्रति यूनिट अधिकतम नुकसान और अधिकतम लाभ?","a":"नेट डेबिट 5। अधिकतम नुकसान ₹5। अधिकतम लाभ 10 − 5 = ₹5।"},{"q":"स्टॉक चढ़ने पर भी ऑप्शन की कीमत क्यों गिर सकती है?","a":"समय क्षय (थीटा) या इम्प्लाइड वोलैटिलिटी का गिरना (वेगा) छोटे दिशात्मक लाभ से ज़्यादा असर डाल सकता है।"}]}};
